/* The few libc routines the compiler may call implicitly (struct copies,
 * zeroing). Freestanding: no other libc. */
void *memset(void *d, int c, unsigned n)
{
    unsigned char *p = d;
    while (n--)
        *p++ = (unsigned char)c;
    return d;
}

void *memcpy(void *d, const void *s, unsigned n)
{
    unsigned char *p = d;
    const unsigned char *q = s;
    while (n--)
        *p++ = *q++;
    return d;
}

static int32_t feel_of(const track_t *t, uint32_t pos, uint32_t next)
{
    uint32_t q = step_samples(t, div_samples((uint32_t)t->p[P_SDIV]), t->seq_idx) / 64u;
    int32_t f;
    if (!q)
        return 0;
    pos = pos < 64u * q ? pos : 64u * q;
    f = next ? -(int32_t)((64u * q - pos + q / 2u) / q) : (int32_t)((pos + q / 2u) / q);   /* (to the nearest 64th) */
    return f < NUDGE_MIN ? NUDGE_MIN : f > NUDGE_MAX ? NUDGE_MAX : f;
}

/* glide: RATE = a fixed speed, TIME = the same time for any interval */
static void glide_set(track_t *t, voice_t *v, int glide)
{
    if (!glide || !v->pitch_cur) {
        v->pitch_cur = v->pitch16;
        v->gstep = 0;
        return;
    }
    if (t->p[P_GLMODE]) {
        int32_t d = v->pitch16 - v->pitch_cur, ticks = 1 + t->p[P_GLIDE] * t->p[P_GLIDE] / 8;
        d = d < 0 ? -d : d;
        v->gstep = d / ticks > 0 ? d / ticks : 1;
    } else {
        v->gstep = 0;
    }
}

static void midi_release(uint32_t ch, uint32_t note)
{
    uint32_t id = midi_notes[ch][note] & 0x7Fu;
    midi_notes[ch][note] = 0;
    if (id) {
        midi_owners[id - 1u]--;
        if (!--midi_ch[ch].owned[id - 1u])
            midi_ch[ch].targets &= (uint8_t)~(1u << (id - 1u));
    }
    if (id) {
        mchord_t *m = mchord_of(ch, note, id);
        uint8_t nn[CHORD_MAX];
        uint32_t n = 1, i;
        nn[0] = (uint8_t)note;
        if (m) {                                  /* a chord: exactly the notes it started */
            n = m->n;
            for (i = 0; i < n; i++)
                nn[i] = m->note[i];
            m->id = 0;
        }
        for (i = 0; i < n; i++)
            if (!midi_local_held(&trk[id - 1u], nn[i]))
                input_off(&trk[id - 1u], nn[i]);  /* input_off also checks other MIDI owners */
    }
}

/* (2.1, #74) key k (as kb_map takes it) of track t is a black key of QNT SOLO: its note alone (no chord), never into the
 * ARP, held by the SMK's pedal only (not KBD HOLD). Not where the engine maps the keys itself */
static int kb_solo(const track_t *t, uint32_t k)
{
    return t->p[P_QUANT] == QN_SOLO && key_black(k) && kb_engine(t, k) < 0;
}

/* the arp's note list (list, its length returned; 0: nothing to play): the held notes (sorted or as played) over OCT
 * octaves, *cnt of them. (Felucca #191) the notes as they play now, a key's mapped again through kb_pitch (TRN, ROOT,
 * SCALE, QNT now, the octave it was pressed in; a chord's note as far above it), the rest (MIDI IN) as they came; each
 * once (two keys may meet on one note now), a key silent now (a black key, QNT WHITE since) left out. With nothing
 * changed since the keys were pressed, exactly the list of held[] as before. (ui_pgraph.c graph_arp draws it) */
static uint32_t arp_list(const track_t *t, uint32_t *list, uint32_t *cnt)
{
    uint32_t i, j, n = 0, x, s, last = 0, len = 0, o;
    const uint8_t *hk = held_key[trk_index(t)];
    const int8_t *dt = held_dt[trk_index(t)];
    for (i = 0; i < t->nheld; i++) {
        x = t->held[i];
        if ((s = hk[i]) != 0u) {
            x = kb_pitch(t, (s & 31u) - 1u, (int32_t)(s >> 5) - 3);
            if (x == KB_SILENT)
                continue;
            x = (uint32_t)clamp((int32_t)x + dt[i], 0, 127);
        }
        last = x;
        for (j = 0; j < n && list[j] != x; j++)
            ;
        if (j == n)
            list[n++] = x;
    }
    *cnt = n;
    if (!t->p[P_AORDER])
        for (i = 1; i < n; i++)
            for (j = i; j > 0 && list[j - 1] > list[j]; j--) {
                x = list[j];
                list[j] = list[j - 1];
                list[j - 1] = x;
            }
    for (o = 0; o < (uint32_t)t->p[P_AOCT]; o++)
        for (i = 0; i < n && len < 64u; i++)
            list[len++] = clamp((int32_t)list[i] + 12 * (int32_t)o, 0, 127);
    if (n && t->p[P_AMODE] == AM_REPEAT) { list[0] = last; len = 1; } /* REPEAT: last played note, no octave traversal */
    return len;
}

/* ---------------------------------------------------------- the SIE --- */
static void sie_wr(uint32_t r, uint32_t v)
{
    uint32_t n = 20000;
    if (!fm1_usb_sie_on())
        return;
    fm1_usb_sie_wr_start(r, v);
    while (!fm1_usb_sie_done() && --n)
        ;
    if (n)
        usb.timeouts = 0;                               /* consecutive failures only */
    else if (++usb.timeouts > 50u)
        usb.up = 0;                                     /* SIE dead (no clock?): stop polling it */
}

/* Normalize in place; 1 = current, 2 = migrated, 0 = invalid. */
static int settings_import_per(persist_t *p, int n)
{
    int current = n == (int)sizeof *p && p->magic == PERSIST_MAGIC;
#if FELUCCA_LEGACY                                 /* ((2.0) PER1..PER3, Felucca's before 1.0: the converter's) */
    int old3 = n == (int)(sizeof *p - sizeof p->favorites) && p->magic == 0x50455233u;
    int old2 = n == (int)(sizeof *p - sizeof p->favorites - sizeof p->bold) && p->magic == 0x50455232u;
    int old1 = n == (int)(8u + sizeof(panel_t)) && p->magic == 0x50455231u;
    if (!(current || old3 || old2 || old1)) return 0;
    if (old1) {
        panel_t old;
        memcpy(&old, (uint8_t *)p + 8, sizeof old);
        p->panel = old;
        p->lowcut = p->zoom = 0;
    }
    if (old1 || old2) p->bold = 0;
    if (!current) memset(&p->favorites, 0, sizeof p->favorites);
#else
    if (!current) return 0;
#endif
    {   /* CLICK, CLICK LEVEL, COUNT-IN (ui.c ui_rec_prefs): two bits each, 3 is no value: the default (0) */
        uint32_t b = p->favorites.factory[15][28], f;
        for (f = 0; f < 3u; f++)
            if (((b >> (2u * f)) & 3u) == 3u)
                b &= ~(3u << (2u * f));
        p->favorites.factory[15][28] = (uint8_t)b;
    }
    if ((p->favorites.factory[15][27] ^ 3u) > 4u)  /* SCREEN OFF (1.1.5, ui.c ui_scr): stored ^ 3, unknown = 0 (30 MIN) */
        p->favorites.factory[15][27] = 0;
    if (p->favorites.factory[15][21] >= 8u)        /* (Skiff phase 9) PRESETS' LIST type (ui.c ui_ptag, below PT_N) */
        p->favorites.factory[15][21] = 0;
    if (p->favorites.factory[15][24] != 0xA5u) {   /* (no Skiff mark: Felucca's or JIANT's settings) [15][18..26]
                                                    * and bit 7 of [28] are theirs (Felucca 1.4's FX keys, LEDS INV, HOME
                                                    * view, AUTO SELECT; JIANT's SKIN, USB, LOAD..), not Skiff's CLOCK MIDI IN
                                                    * TUNE (keys 7 and 15 NONE: CLOCK TRS, PLAY dead), LIST, HINTS,
                                                    * ui_set_rev, KEYS, LAUNCH, FEEL. (2.0) Every byte of Skiff's at its
                                                    * default: row 14 (Skiff's old scenes, then THEME CUSTOM's colours),
                                                    * [15][0..26], MIDI LEARN's map (their numbers aren't Skiff's); [15][27..31]
                                                    * are Felucca's own (SCREEN OFF, CLICK .., MENU's flags), kept */
        memset((uint8_t *)p->favorites.factory + 14u * 32u, 0, 32u + 27u);
        memset(&p->favorites.factory[ENGI_DIGITAL][1], 0, 31);
        p->favorites.factory[15][28] &= 0x7Fu;
        p->favorites.factory[15][24] = 0xA5u;      /* (as Skiff's now: the record read again, the same) */
    }
#if BOARD_SMK37
    if (p->favorites.factory[15][12] >= SMK_KV_N)  /* (SMK-37) KEY VELOCITY (ui.c SMK_KV_BYTE): unknown = DYNAMIC */
        p->favorites.factory[15][12] = 0;
#endif
    p->magic = PERSIST_MAGIC;
    p->palette = palette_to_stored(palette_from_stored(p->palette));
    settings.magic = SETTINGS_MAGIC;
    settings.palette = palette_from_stored(p->palette);
    settings.lowcut = p->lowcut;
    settings.zoom = p->zoom;
    settings_hold = (uint8_t)hold_from_stored(p->bold);
    settings_leds = (uint8_t)leds_from_stored(p->zoom);
#ifdef FELUCCA_FAVORITES
    memcpy(&favorites, &p->favorites, sizeof favorites);
    favorites.filter = favorites.filter == 1u;
#if defined(FM4_NPRESETS) && !FELUCCA_FM4 && FELUCCA_LEGACY
    {   /* DIGITAL's starred presets (engine 1, retired) -> the FM6 presets that cover them (fm4_convert.c) */
        uint32_t k;
        for (k = 0; k < FM4_NPRESETS; k++)
            if ((favorites.factory[ENGI_DIGITAL][0] >> k) & 1u)
                favorites.factory[ENGI_FM6][FM4_TO_FM6[k] / 8u] |= (uint8_t)(1u << (FM4_TO_FM6[k] % 8u));
        favorites.factory[ENGI_DIGITAL][0] = 0;  /* ((1.3) bytes 2..31: MIDI LEARN's map, midi_control.c ML_N) */
    }
#endif
#if defined(SMP_SET_PERC) && FELUCCA_LEGACY
    if ((favorites.factory[ENGI_SAMPLE][0] >> SMP_SET_PERC) & 1u) {   /* SAMPLE's PERC (preset 4, retired): DRUM's */
        favorites.factory[ENGI_DRUM][0] |= 1u;                         /* kit (core.h drum_from_perc) */
        favorites.factory[ENGI_SAMPLE][0] &= (uint8_t)~(1u << SMP_SET_PERC);
    }
#endif
#endif
    if (p->panel.magic == PANEL_MAGIC) panel = p->panel;
    return current ? 1 : 2;
}

static int32_t cv_text_on(int32_t x, int32_t y, const aafont_t *f, const char *s, uint16_t fg, uint16_t bg)
{
    return cv_text_flags(x, y, f, s, fg, bg, 0);
}

/* the car (side on, facing right: its tail light T, the glass, the headlight, the wheels), z times its size, in a 1 px
 * dark outline; its light trails behind it from the tail light's row, `len` px, fading into `under`. SPR_CAR 18 x 6 (the
 * splash), SPR_CAR24 24 x 8 (HOME: the user's "a little smaller" than SPR_CAR at 2x; tools/gen_sprites.py) */
static void ne_car(int32_t x, int32_t y, const uint8_t *car, int32_t z, uint16_t body, int32_t len, uint16_t under)
{
    const uint16_t ol[5] = {T_BG, T_BG, T_BG, T_BG, T_BG}, cols[5] = {body, T_ACCENT, NE_RED, NE_YELLOW, T_BG};
    int32_t i, t;
    for (t = 0; t < car[1] && spr_px(car, (uint32_t)t * car[0]) != 3u; t++)   /* (the tail light: key 3, T) */
        ;
    for (i = 0; i < len; i++) {                       /* the trails: the tail light's red, a cyan streak under it */
        cv_rect(x - 1 - i, y + t * z, 1, z, ux_mix(NE_RED, under, i * 100 / len));
        cv_rect(x - 1 - i, y + (t + 1) * z + 1, 1, 1, ux_mix(T_ACCENT, under, i * 140 / len < 100 ? i * 140 / len : 100));
    }
    for (i = 0; i < 4; i++)
        ui_sprite(x + (i == 0) - (i == 1), y + (i == 2) - (i == 3), car, 5u, ol, z);
    ui_sprite(x, y, car, 5u, cols, z);
}

/* every value inside its range (a name byte outside 32..126 becomes a space) */
static void fm6_sanitize(uint8_t *v)
{
    uint32_t i;
    for (i = 0; i < FP_SIZE; i++) {
        if (i >= FP_NAME)
            v[i] = v[i] < 32u || v[i] > 126u ? ' ' : v[i];
        else if (v[i] > fm6_max(i))
            v[i] = (uint8_t)fm6_max(i);
    }
    v[FP_SIZE] = 0;
}

/* SLOT value s < FM6_NFACTORY: that factory patch into track tr */
static void fm6_load_slot(uint32_t tr, uint32_t s)
{
    uint8_t v[FP_SIZE + 1u];
    fm6_unpack(FM6_FACTORY[s % FM6_NFACTORY], v);
    fm6_set_patch(tr, v);
    fm6_slot[tr % NTRK] = (uint8_t)(s % FM6_NFACTORY);
}

/* the same, its ink centred on the line cy (between rows cy - 1 and cy: the middle of rows 0 .. 2 cy - 1, the odd row
 * left over going up; header icons: each glyph sits differently in its cell) */
static int32_t cv_icon_mid(int32_t x, int32_t cy, uint32_t size, uint32_t id, uint16_t fg, uint16_t bg)
{
    GFX_HOOK_ALIGN(0, 0, 0, 2 * cy, AL_V | AL_PASS, "header icon on its middle");
    return cv_icon_in(x, 0, 0, 2 * cy, size, id, fg, bg);
}

/* a project load (project.c, the transport stopped, the ISR off): nothing staged comes in over it (what went out at a
 * swap before it: kept first, project_load) */
static void launch_drop(void)
{
    uint32_t k;
    for (k = 0; k < NTRK; k++)
        launch_q[k].armed = launch_q[k].done = mute_arm[k] = 0;
}

static uint32_t ed_unpack7(const uint8_t *a, uint32_t na, uint8_t *out, uint32_t max)
{
    uint32_t n = 0;
    while (na && n < max) {
        uint32_t m = *a++, j;
        na--;
        uint32_t k = na > 7u ? 7u : na;
        if (!k || n + k > max || (m >> k))
            return 0;
        for (j = 0; j < k; j++, na--)
            out[n++] = (uint8_t)(*a++ | ((m >> j) & 1u) << 7);
    }
    return na ? 0u : n;
}

static void ed_ui_state(void)
{
    uint32_t sig = 0;
    ed_b(ed_ui_caps());
    ed_b(menu_get(MI_COLOR));                          /* ((Skiff #27) NPALETTES: CUSTOM) */
    ed_b(127);                                         /* font: not supported */
#ifdef FELUCCA_MONITOR
    ed_b(settings.monitor);
#else
    ed_b(127);
#endif
#ifdef FELUCCA_FAVORITES
    ed_b(favorites.filter);
    sig = 2166136261u;
    for (uint32_t i = 0; i < sizeof favorites; i++)
        sig = (sig ^ ((const uint8_t *)&favorites)[i]) * 16777619u;
#else
    ed_b(127);
#endif
    ed_u28(sig);
    ed_u28(up_gen);
}

/* ------------------------------------------------------- track setup --- */
static int seq_is_empty(const track_t *t)
{
    uint32_t i;
    for (i = 0; i < NSTEP; i++)
        if (t->step[i].n || t->step[i].hit)
            return 0;
    return 1;
}

/* track k kept: its pattern, changed since it came in (trk_sig), waits to be written (pat_keep_rec); steps on no
 * pattern yet become a new one, the first free id (trk_name). 0 kept (or unchanged, or nothing there), 1 not: PATTERNS
 * FULL (no id, no waiting slot) */
static int trk_keep(uint32_t k)
{
    uint32_t h, id;
    k %= NTRK;
    if (!BK_ON)
        return 0;
    if (!trk_pid[k] && seq_is_empty(&trk[k]) && !motion_count(&trk[k]))
        return 0;                                  /* (nothing there: nothing to keep) */
    if (!trk_rec(k))
        return 1;
    h = proj_hash(bk_rec, BK_REC);
    if (trk_pid[k] && h == trk_sig[k])
        return 0;
    id = trk_pid[k] ? trk_pid[k] - 1u : pool_alloc();
    if (id == NPAT || pat_keep_now(id, bk_rec))
        return 1;
    if (!trk_pid[k])
        trk_name(k, id);
    trk_sig[k] = h;
    return 0;
}

/* ---- (2.0, #30) a song entry's sound (b: lists.snd's two bytes: 0 0 none; engine + 1 and its preset; 0x80 + a user
 * slot, 0), as PRESETS or USER loads it: all but the track's own values (param_kept). Made into s for track k; 0: none
 * (none set, its user slot erased since, an engine the track may not play: the track's sound stays) ---- */
static int esnd_make(uint32_t k, const uint8_t *b, esnd_t *s)
{
    uint32_t eng = b[0] - 1u, u = b[0] & 127u, pi;
    s->kit = s->fm6 = 0;
    if (b[0] & 128u) {
        if (u >= UP_SLOTS || !up_used(u) || !eng_allowed(k, up_engine(u)))
            return 0;
        up_values(up_rec(u), s->p);
        s->eng = (uint8_t)up_engine(u);
        s->preset = 0;
        s->user = (uint8_t)(u + 1u);
        if (s->eng == ENGI_FM6) {                  /* (its own patch, SLOT as up_load shows it) */
            upf_patch(u, s->p[P_E7], s->f6);
            s->p[P_E7] = (int16_t)fm6_match(s->f6, s->p[P_E7]);
            s->fm6 = 1;
        }
        return 1;
    }
    if (!eng_ok(eng) || !ENGINES[eng]->npresets || !eng_allowed(k, eng))   /* (eng_ok: not DIGITAL's, retired) */
        return 0;
    pi = preset_orig(ENGINES[eng], b[1] % ENGINES[eng]->npresets);
    preset_fill(s->p, ENGINES[eng], pi);
    s->eng = (uint8_t)eng;
    s->preset = (uint8_t)pi;
    s->user = 0;
    if (eng == ENGI_DRUMX)
        s->kit = DRUMX_PKIT[pi % NELEM(DRUMX_PKIT)];
    if (eng == ENGI_FM6 && s->p[P_E7] >= 0 && s->p[P_E7] < (int32_t)FM6_NFACTORY) {
        fm6_unpack(FM6_FACTORY[s->p[P_E7]], s->f6);
        s->fm6 = 1;
    }
    return 1;
}

/* each frame (ui_input): a swap the ISR made (done): what played (now in launch_q) is kept as the pattern it was (a new
 * one: a new id, named by the entry it was on), and the track is on the entry that came in; a pattern or a mute still
 * staged when the transport stopped comes in now, as while stopped (a song's next not: PLAY stages it again; a
 * project load drops them: launch.c launch_drop). (#29) What went out changed and no waiting slot free (playing: they
 * are written stopped): it waits in q (done 2: nothing staged for the track meanwhile, stage_entry), the track counted
 * on the entry it left, until stopped (a chunk written then to make room) */
static void bank_poll_trk(uint32_t k)
{
    launch_t *q = &launch_q[k];
    track_t *t = &trk[k];
    uint32_t id;
    int rc = 0;
    if (mute_arm[k] && !song.playing) {
        t->p[P_MUTE] = (int16_t)(mute_arm[k] - 1u);
        mute_arm[k] = 0;
    }
    if (q->armed && !song.playing) {
        q->armed = 0;
        if (!q->adv)
            (void)ent_go(k, q->slot);
        q->adv = 0;
        return;
    }
    if (!q->done)
        return;
    if (q->snd) {                                  /* ((2.0, #30) the entry's sound came in: MOMENTARY's values for */
        q->snd = 0;                                /* the sound before stay out of it) */
        mom_drop(t);
        if (t == TSEL)
            sync_reload = 1;
    }
    if (q->done == 2u && transport_busy())
        return;
    if (!q->same && (trk_pid[k] || !q_empty(q)) &&     /* ((2.0.3, #71) the same pattern: nothing went out) */
        bk_pack_raw(bk_rec, k, q->step, q->time, &q->motion, (q->motion.on >> k) & 1u)) {
        id = trk_pid[k] ? trk_pid[k] - 1u : pool_alloc();   /* (a new pattern went out: the first free id) */
        if (trk_pid[k] && ((motion_lost >> k) & 1u))
            rec_motion_of(bk_rec, id);
        if (trk_pid[k] && proj_hash(bk_rec, BK_REC) == trk_sig[k])
            ;                                      /* (unchanged since it came in) */
        else if (id == NPAT || (rc = pat_keep_now(id, bk_rec)) != 0) {
            if (rc && transport_busy()) {
                if (q->done == 1u)
                    ui_way("PATTERNS FULL", "STOP TO SAVE");
                q->done = 2;
                return;
            }
            ui_way("PATTERNS FULL", WAY_PATTERNS);   /* (no id for it; stopped, a flash error) */
        } else if (!trk_pid[k])
            trk_name(k, id);
    }
    q->done = 0;
    {   /* ((2.0, #44) a chain's own next from one of its parts: its passes go on (its first after its last: one more);
         * else in a chain anew. Its first coming in: the pass it starts on, and (round from its last) the one its pass
         * before started on: TAKE's) */
        uint32_t b0, b1, e = q->slot % NENT, o = lists.cur[k] % NENT, in = (uint32_t)ent_block(k, e, &b0, &b1);
        uint32_t own = in && q->adv && o >= b0 && o <= b1;
        if (!own)
            chain_rep[k] = 0;
        else if (e == b0 && o == b1 && chain_rep[k] < 255u)
            chain_rep[k]++;
        if (in && e == b0) {
            chain_pl[k] = own && o == b1 ? chain_p0[k] : 0u;
            chain_p0[k] = (uint16_t)(take_p0[k] + 1u);
        }
    }
    q->adv = 0;
    trk_pid[k] = (uint8_t)(q->id == PAT_NONE ? 0u : q->id + 1u);   /* ((1.2.1, #12) a rest: on no pattern) */
    lists.cur[k] = (uint8_t)(q->slot % NENT);
    if (!q->same) {                                /* ((2.0.3, #71) the same pattern: its copy and automation as they
                                                    * came in before, so an edit since is still kept when it goes out */
        trk_sig[k] = q_sig[k];
        motion_lost = (uint8_t)((motion_lost & ~(1u << k)) | (q->mlost ? 1u << k : 0u));
    }
    bk.gen++;
    ui.force = 1;
}

/* the object to flash: 0 ok, 2 flash error, 3 no flash (kept in RAM). Its first write keeps the retired bank's
