/* .. CLEAR UNUSED (its dialog's OCT+, stopped): every pattern nothing uses, cleared. Said: how many */
static void pool_clear_unused(void)
{
    char b[24];
    uint32_t id, n = 0;
    int rc = 0;
    if (!BK_ON || transport_busy()) {
        ui_message(!BK_ON ? "STORAGE ERROR" : "STOP TO CLEAR");
        return;
    }
    memset(bk_rec, 0, BK_REC);
    for (id = 0; id < BK_POOL && !rc; id++)
        if (pool_used(id) && !pool_refs(id)) {
            if (pat_keep_now(id, bk_rec))
                rc = 4;
            else
                n++;
        }
    if (pool_flush_said(rc))
        return;
    str_cpy(b, "CLEARED ", sizeof b);
    fmt_int(b + 8, (int32_t)n);
    str_cpy(b + str_len(b), n == 1u ? " PATTERN" : " PATTERNS", sizeof b - str_len(b));
    ui_message(b);
}

/* the launch_steps a BAR / BEAT launch staged now comes in on: the next bar's, beat's */
static uint32_t launch_at(uint32_t m)
{
    return m == LAUNCH_BAR ? (launch_steps / 16u + 1u) * 16u : (launch_steps / 4u + 1u) * 4u;
}

/* slot k's name, upper case, 0-terminated (b holds 13); ((2.0) none there "--", a sound of a format of before OLD FORMAT:
 * the question before SAVE writes over it) */
static void up_name(uint32_t k, char *b)
{
    const char *s = up_used(k) ? up_rec(k)->name : up_old(k) ? "OLD FORMAT" : "--";
    uint32_t i;
    for (i = 0; i < 12u && s[i]; i++)
        b[i] = s[i] >= 'a' && s[i] <= 'z' ? (char)(s[i] - 32) : s[i];
    b[i] = 0;
}

/* OCT- in the PERFORM layer: nothing staged comes in after all, no track's pattern, no mute: 1 there was some (a song's
 * next not: it is the song, staged again at once) */
static int stage_cancel(void)
{
    uint32_t k;
    int was = 0;
    for (k = 0; k < NTRK; k++) {
        if (user_staged(k))
            was |= bank_cancel(k);
        was |= mute_arm[k] != 0u;
        mute_arm[k] = 0;
    }
    bk.gen++;
    return was;
}

/* the locks of track t's step (NSTEP and up: of every step); their automation events stay. A lock sounding now goes
 * back at the next step as always (motion_locked). The locks it removed */
static uint32_t motion_clear_locks(track_t *t, uint32_t step)
{
    uint32_t f = motion_guard(), k = trk_index(t), i, n = 0, gone;
    for (i = 0; i < motion.count; i++) {
        const motion_event_t *e = &motion.event[i];
        if ((e->place >> 6) == k && e->lock && (step >= NSTEP || (e->place & 63u) == step)) continue;
        motion.event[n++] = *e;
    }
    gone = motion.count - n;
    memset(motion.event + n, 0, (MOTION_MAX - n) * sizeof motion.event[0]);
    motion.count = (uint8_t)n;
    motion_unguard(f);
    return gone;
}

static void project_load(uint32_t slot)
{
    mom_back(0);                                  /* ((1.3) MOMENTARY: the values as they were, then the load) */
    memset(drum_mute, 0, sizeof drum_mute);       /* ((1.3) the DRUM lanes' mutes, performance state) */
#if FELUCCA_FLASH
    if (flash_ok && !proj_import(&proj_scratch, &proj_slot[slot & 3u], sizeof(project_store_t))) proj_fetch(slot);
#endif
    if (!proj_import(&proj_scratch, &proj_slot[slot & 3u], sizeof(project_store_t))) {
        ui_message(proj_old(slot) ? "OLD FORMAT" : "EMPTY SLOT");   /* ((2.0) converted by the editor's Restore) */
        return;
    }
    proj_bound(&proj_scratch);                          /* a retained RAM slot of an older format: as from flash */
    transport_stop_now();                               /* (phase 5) stopped first (the ISR swaps nothing more, the */
    (void)stage_cancel();                               /* steps are still while kept), nothing staged comes in; */
                                                        /* what the tracks have kept (a swap made: what went out) */
    if (keep_all() == 1) {
        ui_way("PATTERNS FULL", WAY_PATTERNS);
        return;
    }
    if (!project_restore_runtime(&proj_scratch)) {
        proj_cur = (uint8_t)(slot & 3u);
        project_clean();
    }
}

/* the sound's name on the track: a user preset or the engine's preset (b holds 16); (FM6 LAB) an FM6 track on its own
 * patch (edited, INIT's): the patch's name ("INIT VOICE"); ((2.0, #35) DRUM on a user kit: its slot's name, "MY KIT") */
static void sound_name(const track_t *t, char *b)
{
    const engine_t *e = ENGINES[t->eng_req % NENGINES];
    uint32_t u = t->eng_req % NENGINES == ENGI_DRUM ? drum_user(t->p) : 0u;
    b[0] = 0;
    if (user_of(t) < UP_SLOTS)
        up_name(user_of(t), b);
    else if (u && usr_nz[u - 1u])
        smp_user_name(u - 1u, b);
    else if (t->eng_req % NENGINES == ENGI_FM6 && t->p[P_E7] == FM6_OWN) {
        uint32_t n = 10;
        memcpy(b, fm6_patch[trk_index(t) % NTRK] + FP_NAME, 10);
        while (n && b[n - 1u] == ' ')
            n--;
        b[n] = 0;
    } else if (e->npresets)
        str_cpy(b, e->presets[t->preset % e->npresets].name, 16);
}

/* OCT+ (apply: the emptied steps lose their locks) or OCT- (cancel: the steps of the copy back) */
static void eu_close(track_t *t, int apply)
{
    uint32_t len;
    if (!eu.on)
        return;
    t = eu_track();
    len = tl_len(t);
    eu.on = 0;
    if (apply) {
        tl_unlock(t, tl_used_of(eu_from, len), len);
        return;
    }
    memcpy(t->step, eu_from, sizeof t->step);
}

/* the armed layer lets go (its button up, or its lock closed): FX's macros come back once its map has gone ((2.0, D 2A)
 * over RETURN: ui.c mom_poll; (2.0.3, #69) not while a key pressed with FX is held; FX LATCH: they stay while it is
 * locked); one that opened, or a combo: KNOB 1..4 quiet for a while (#39: the
 * knob still turning is not the page's) */
static void layer_let_go(uint32_t quiet)
{
    if (eu.on)                                          /* ((1.3) SEQ TOOLS: an open EUCLID is applied) */
        eu_close(&trk[lys.trk % NTRK], 1);
    if (ui.ly == LAYER_FX)                              /* (a lock let go: its latched effects with it) */
        perf_latched = 0;
    upin.pin = 0;                                       /* ((2.0) SEQ TOOLS', REC's put-back: the ring as ever) */
    upin.pin_next = 0;
    lys.clr_t = 0;
    if (lys.rp_dirty) {                                 /* REC: its settings kept, as MENU does when it closes */
        lys.rp_dirty = 0;
        settings_save();                                /* (deferred while playing) */
    }
    if (quiet) {
        lys.quiet = 1;
        lys.quiet_t = fm1_ms;
    }
    ui.ly_t0 = 0;
    ui.ly = 0;
    ui.lock = 0;
}

/* switch engine (its defaults + first preset) and say so; 1: refused (said) */
