static int32_t enum_rank(const param_desc_t *d, int32_t v)   /* v's place in the shown order (+ min): the gauges */
{
    const uint8_t *o = enum_order(d);
    int32_t r;
    for (r = 0; o && r < d->max - d->min; r++)
        if (o[r] == v - d->min)
            break;
    return o ? r + d->min : v;
}

/* VELOCITY: every selected step's by the same amount (0, a hit's or an old step's: seq.c's 96) */
static void sel_velocity(track_t *t, int32_t d)
{
    uint32_t i;
    if (sel_first(t) == NSTEP)
        return;
    run_undo(t, SN_VEL);
    for (i = sel_lo(); i <= sel_hi(); i++)
        if (sel_step(t, i))
            t->step[i].vel = (uint8_t)clamp((int32_t)step_vel(&t->step[i]) + d, 1, 127);
    run_done(t);
}

/* how many steps the notes starting at i sound: 1 + the TIEs after it ((2.0) its longest note) */
static uint32_t step_span(const track_t *t, uint32_t i)
{
    uint32_t len = (uint32_t)t->p[P_SLEN], n = 1, k, m;
    for (k = 0; k < t->step[i].n; k++)
        if ((m = note_span(t, i, k)) > n)
            n = m;
    while (!t->step[i].n && i + n < len && t->step[i + n].time == ST_TIE)
        n++;
    return n;
}

/* list index n (< total) -> engine, *k its preset; NENGINES = user preset, *k its slot */
static uint32_t preset_all_at(uint32_t n, uint32_t *k)
{
    uint32_t e = 0, i, r;
    for (r = 0; r < NENG_SHOWN && n >= preset_listed(eng_vis(r)); r++)
        n -= preset_listed(eng_vis(r));
    if (r == NENG_SHOWN) {
        *k = up_nth(n);
        return NENGINES;
    }
    e = eng_vis(r);
    for (i = 0; preset_orig(ENGINES[e], i) != i || n--; i++)    /* the n-th shown preset */
        ;
    *k = i;
    return e;
}

/* the menu's step, any of KNOB 1..4 or OCT+ (s > 0) / OCT- (s < 0): the next / previous value, stopping at the ends;
 * THEME (MI_COLOR) wraps round its palettes. On an ON / OFF row up is ON (MENU_FLAGS) */
static uint32_t menu_step(uint32_t row, int32_t s)
{
    const menu_flag_t *f = menu_flag(row);
    uint32_t v = menu_get(row), n = menu_n(row);
    if ((f && str_eq(f->name[0], "ON")) || row == MI_HINTS)   /* (ANIM, USB SERIAL, RESTORE LAST, HINTS: ON is their
                                                                * value 0) */
        s = -s;
    if (s > 0)
        return v + 1u < n ? v + 1u : row == MI_COLOR ? 0u : v;
    if (s < 0)
        return v ? v - 1u : row == MI_COLOR ? n - 1u : 0u;
    return v;
}

/* a page button let go (they act on release; a layer's own button: layer_gesture). 1: it acted (EDIT on NOTES, USER,
 * PROJECT) instead of opening a page */
static int page_tap(uint32_t b)
{
    uint32_t f;
    if (b == B_GLO) {
        open_global();                                  /* MIXER -> GLOBAL -> SYSTEM -> MIXER */
        return 0;
    }
    if (b == B_EDIT && song.seq_mode && !ui.home && step_page(cur_page()->graph) &&
        (lock_held() || ((song.rec >> song.sel) & 1u))) {   /* STEP: a step held, its locks; (Skiff U2) armed, EDIT
                                                         * deletes the cursor step (step entry); else the EDIT pages */
        uint64_t held = lock_held();
        if (held) {                                     /* a step held: its locks (the step stays) */
            lock_clear(held);
            return 1;
        }
        step_clear_undo(TSEL);                          /* (Skiff U1) SAVE held puts it back */
        step_clear_ties(TSEL, ui.cursor);               /* ((2.0) its notes' ties too; (#44) a chain's tail) */
        chain_sync(TSEL);
        undo.after = track_sig(TSEL);
        undo.t_ms = fm1_ms;
        cursor_set(ui.cursor + 1);
        ui_message("STEP CLEARED");
        return 1;
    }
    /* ((Skiff U2, the review's G3) AUTO LIST's delete, SONG's clear, USER / PROJECT's rename: their cards now) */
    for (f = FAM_HOME + 1u; f < FAM_COUNT; f++)
        if (FAM_BTN[f] == b) {
            open_family(f);
            return 0;
        }
    return 0;
}

/* keycap / badge `id` with its top-left at (x, y), KC_H tall: fill and label tinted with tokens, `under` what lies
 * behind its corners; returns its right edge */
static int32_t cv_keycap(int32_t x, int32_t y, uint32_t id, uint16_t fill, uint16_t ink, uint16_t under)
{
    const kc_t *k = &KC[id < KC_COUNT ? id : 0u];
