    return cv_text_on(x, y + KC_TY, &AF_S, k->label, fill == T_KEY ? T_MID : fill, under);
}

static const char *page_head(void)
{
    static char hb[16];
    const page_t *pg = cur_page();
    const sheet_t *sh = sheet_of(pg->graph);
    uint32_t off, all;
    if (sh)
        return sh->title();
    if (pg->scope == SC_ENGINE)                         /* ((Skiff U4, L5) EDIT: the engine's own name (OSC, KIT), the
                                                         * footer only where it is (n/m); the footer said it before) */
        return ENGINES[TSEL->eng_req % NENGINES]->page_title[pg->id[0] != P_E0];
    if (!(step_page(pg->graph) || pg->graph == GR_FEEL))
        return pg->title;
    off = step_off(&all, 1);                            /* ((2.0, #44) a chain's steps counted on: NOTES 69) */
    str_cpy(hb, pg->title, sizeof hb);
    str_cpy(hb + str_len(hb), " ", 2);
    fmt_int(hb + str_len(hb), (int32_t)(sel_lo() + off) + 1);
    if (nsel.a1) {
        str_cpy(hb + str_len(hb), "-", 2);
        fmt_int(hb + str_len(hb), (int32_t)(sel_hi() + off) + 1);
    }
    return hb;
}

#define LG_LY 24                                        /* the label's line: M capitals rows 28..38 */
#define LG_VB 49                                        /* the value's band: L capitals rows 49..69 */
#define LG_UY 73                                        /* the unit's line (S capitals rows 76..84) */
#define LG_GY 92                                        /* the gauge, 3 px */
/* a tall card's value s in L where the sparse L face has its glyphs and it fits with 3 px either side, else M, else S
 * (0, 1, 2; its unit is on a line of its own) */
static uint32_t tall_face(const char *s, const char *unit)
{
    (void)unit;
    if (large_face_has(s) && ink_w(&AF_L, s) + (ux.neon ? cv_fx_w(&AF_L) : 0) <= COL_W - 6)   /* ((Skiff N2) NEON: */
        return 0u;                                                                             /* slanted, the wider) */
    return ink_w(&AF_M, s) + (ux.neon ? cv_fx_w(&AF_M) : 0) <= COL_W - 6 ? 1u : 2u;
}

/* "1.234": samples of s as seconds */
static void slice_time(char *b, uint32_t n)
{
    uint32_t src, div, hz;
    const slc_src_t *s = slice_src(&src, &div);
    hz = s ? (s->rate >> 4) * 44100u >> 12 : 0u;    /* (as slc_scan) */
    fmt_fix(b, (int32_t)((uint32_t)n * 1000u / (hz ? hz : 1u)), 3);
    if (b[0] == '.') {                               /* fmt_fix writes ".255": "0.255" */
        uint32_t i = str_len(b) + 1u;
        for (; i; i--)
            b[i] = b[i - 1u];
        b[0] = '0';
    }
}

/* the MOD page: the icon of a source, of a destination (an engine parameter: its own) */
static uint32_t mod_src_icon(int32_t s)
{
    static const uint8_t I[MS_N] = {ICON_MOD, ICON_LFO_WAVE, ICON_ENV, ICON_ACCENT, ICON_KEYTRACK, ICON_PROB,
                                    ICON_MOD, ICON_MIDI, ICON_LEVEL, ICON_ENV};   /* ((Skiff phase 9) ENV2: ENV's) */
    return I[clamp(s, 0, MS_N - 1)];
}

/* the rows lit by keys held on the selected track (bit r: row r from the top) */
static uint32_t pr_held(void)
{
    uint32_t k, i, m = 0;
    for (k = 0; k < KB_N; k++)
        if (kb_chn[k] && kb_trk[k] == song.sel)
            for (i = 0; i < kb_chn[k]; i++) {
                int32_t r = (int32_t)proll.lo + PR_ROWS - 1 - kb_chord[k][i];
                if (r >= 0 && r < PR_ROWS)
                    m |= 1u << r;
            }
    return m;
}

/* the sun's bands under a curve: column x from below y to the foot, gold at `top` to pink and purple at the foot, cut
 * by gaps that widen downward, dimmed into the glass (ne_bands: a curve's columns, ys[i] at x0 + i) */
static void ne_band_col(int32_t x, int32_t y, int32_t top, int32_t foot)
{
    for (y += 3; y < foot; y++) {
        int32_t t = (y - top) * 1000 / (foot - top);
        if (t > 350 && (y % 5) < 1 + (t - 350) * 6 / 1000)
            continue;
        cv_rect(x, y, 1, 1, ux_mix(ne_ramp(NE_SUNSET, 4, t), T_SURF, 30));
    }
}

/* Matches voice.c: attack is linear, decay and release are exponential
 * (env += (target - env) * k each tick, ~99 % after the set time). Time
 * axis is the parameter value (the times themselves are exponential). */
static void graph_adsr(const track_t *t, uint16_t c)
{
    const page_t *pg = cur_page();
    int32_t a = 4 + t->p[pg->id[0]] * 50 / 127, d = 6 + t->p[pg->id[1]] * 50 / 127, r = 6 + t->p[pg->id[3]] * 60 / 127;
    int32_t top = 6 * graph_ht / 100, bot = 88 * graph_ht / 100, sus = t->p[pg->id[2]] * 1000 / 127;   /* 0..1000 */
    int32_t x0 = 12, x1 = x0 + a, x3 = 226 - r, i, px, py;
    int32_t e = 32768;                                                  /* exp(-4.6 u), Q15 */
    if (ux.crypt) {                                  /* (Skiff C4) CRYPT: its own */
        cr_adsr(t);
        return;
    }
#define EGY(lvl) (bot - (lvl) * (bot - top) / 1000)
    if (ux.neon || ux.quark) {                       /* (Skiff N4) NEON: the sun's bands under the curve; (Q4) QUARK: a
                                                      * Monte Carlo fill */
        int32_t xa, xd, xr;
        env_fill4(t->p[pg->id[0]], t->p[pg->id[1]], t->p[pg->id[2]], t->p[pg->id[3]], eg_lv, 214, &xa, &xd, &xr);
        for (i = 0; i <= 214; i++)
            eg_lv[i] = (int16_t)EGY(eg_lv[i]);     /* (the rows) */
        if (ux.neon)
            ne_bands(x0, eg_lv, 215, top, bot);
        else
            for (i = 0; i <= 214; i++)
                qk_mc(x0 + i, eg_lv[i], bot);
    }
    cv_rect(PANEL_X0, top, PANEL_W, 1, T_LINE);      /* (Skiff) as the B mockup: three guides, its top, middle, foot */
    cv_rect(PANEL_X0, (top + bot) / 2, PANEL_W, 1, T_LINE);
    cv_rect(PANEL_X0, bot, PANEL_W, 1, T_LINE);
    cv_line_t(x0, bot, x1, top, c, 2);                                  /* attack: linear */
    px = x1;
    py = top;
    for (i = 1; i <= d; i++) {                                          /* decay: exponential to SUS */
        int32_t lvl;
        e = (e * (32768 - 150733 / d)) >> 15;           /* k^d = exp(-4.6) */
        lvl = sus + ((1000 - sus) * e >> 15);
        cv_line_t(px, py, x1 + i, EGY(lvl), c, 2);
        px = x1 + i;
        py = EGY(lvl);
    }
    cv_line_t(px, py, x3, EGY(sus), c, 2);                               /* sustain */
    px = x3;
    py = EGY(sus);
    e = 32768;
    for (i = 1; i <= r; i++) {                                          /* release: exponential to 0 */
        e = (e * (32768 - 150733 / r)) >> 15;
        cv_line_t(px, py, x3 + i, EGY(sus * e >> 15), c, 2);
        px = x3 + i;
        py = EGY(sus * e >> 15);
    }
    {                                                /* (Skiff) and its points as 5 px blocks, as the mockup's: the
                                                      * peak (ATK), the decay's end (DEC), the release's start (REL),
                                                      * SUS both of the last two; the knob just turned's white */
        int32_t hc = ui.hot_t ? (int32_t)ui.hot_col : -1, hx[3] = {x1, x1 + d, x3}, hy[3] = {top, EGY(sus), EGY(sus)};
        for (i = 0; i < 3; i++) {                    /* (the peak lit by ATK; the decay's end by DEC, SUS; the release's
                                                      * start by SUS, REL) */
            int hot = hc == i || (i && hc == i + 1);
            if (ux.quark)                            /* ((Skiff Q4) QUARK: nuclei, the knob just turned's gold) */
                qk_nucleus(hx[i], hy[i], hot ? T_ACCENT : T_THEME, hot ? 9 : 7);
            else if (ux.neon)                        /* ((Skiff N4) NEON: sparkles, the knob just turned's big) */
                ne_spark(hx[i], hy[i], hot ? T_THEME : T_ACCENT, hot ? 2 : 1);
            else
                cv_rect(hx[i] - 2, hy[i] - 2, 5, 5, hot ? T_ACCENT : c);
        }
        if (ux.quark) {                              /* ((Skiff Q4) QUARK: DECAY's and RELEASE's half-lives over the
                                                      * sustain (under it near the top) */
            char hb[16];
            int32_t ly = EGY(sus) - 14 < 2 ? EGY(sus) + 6 : EGY(sus) - 14, lx = x1 + d + 10, rx;
            if (pg->id[1] == P_DEC) {                /* (the ENV page's own envelope: its times' table) */
                qk_halflife(hb, t->p[P_DEC]);
                if (lx + text_w(&AF_S, hb) <= 230)   /* (in the panel, or none) */
                    lx = cv_text(lx, ly, &AF_S, hb, hc == 1 ? T_ACCENT : T_MID) + 6;
                else
                    lx = 240;
                qk_halflife(hb, t->p[P_REL]);
                rx = x3 - 8 - text_w(&AF_S, hb);
                if (rx >= lx && rx > x1 + d)
                    cv_text(rx, ly, &AF_S, hb, hc == 3 ? T_ACCENT : T_MID);
            }
        }
    }
#undef EGY
}

/* (2.0, #35) user kit slot k's sample for lane l: the narrowest zone holding the lane's note (DRUM_LANE_NOTE, as
 * SAMPLE picks one), as a voice keeps it (0x8000 | k << 5 | zone); 0 none: the lane silent */
static uint32_t drum_user_zone(uint32_t k, uint32_t l)
{
    uint32_t i, zi = 0, w = 128u, note = DRUM_LANE_NOTE[l & (NLANE - 1u)];
    k %= SMP_USER_SLOTS;
    for (i = 0; i < usr_nz[k]; i++) {
        const smp_zone_t *z = &usr_zone[k][i];
        if (note >= z->lo && note <= z->hi && (uint32_t)(z->hi - z->lo) <= w) {
            zi = 0x8000u | k << 5 | i;
            w = (uint32_t)(z->hi - z->lo);
        }
    }
    return zi;
}

/* the operator with feedback in algorithm a (0..5: operator 1..6) */
static uint32_t fm6_fb_op(uint32_t a)
{
    uint32_t k;
    for (k = 0; k < 5u && (FM6_ALG[a & 31u][5u - k] & 0xC0u) != 0xC0u; k++)
        ;
    return k;
}

/* the icon beside a page's title in the footer (the pages that have one of their own; else ICON_NONE) */
static uint32_t page_icon(const page_t *pg)
{
    switch (pg->graph) {
    case GR_TRK: return ICON_X_MIXER;         /* MIXER (GLO): vertical faders */
    case GR_BANK: return ICON_X_PATTERN;      /* (Skiff) SAVE > PATTERNS: the bank */
    case GR_SONG: return ICON_X_SONG;         /* (Skiff phase 5) SONG: the disc */
    case GR_FEEL: return ICON_PROB;           /* (Skiff 2.0) FEEL: the die (CHANCE's) */
    case GR_EVENTS: return motion_icon();     /* AUTOMATION ((Skiff U3) the list) */
    default: return ICON_NONE;
    }
}

/* action pages: the footer's first row says what OCT+ and OCT- do ("OCT+ LOAD   OCT- BACK") */
static void foot_hint(char *a, char *b)
{
    uint32_t c = act_col();
    str_cpy(a, "OCT+ ", 8);
    str_cpy(a + 5, c ? act_name(c - 1u) : "--", 19);   /* ((2.0) CLEAR 3 UNUSED, COPY 06 TO 22 AT F: a 24-byte a) */
    str_cpy(b, ui.act || ui.ev_del ? "OCT- CANCEL" : "OCT- HOME", 16);   /* ((Skiff U2) where it goes: HOME, not "BACK") */
}

static void draw_foot(void)
{
    char s[48], pn[16], ti[20];
    const track_t *t = TSEL;
    uint32_t sig;
    const page_t *pg = cur_page();
    const engine_t *e = ENGINES[TSEL->eng_req % NENGINES];
    const char *ename = e->name;
    int32_t x, ly = foot_line_y();                     /* (BLOCKS: the one line) */
    int tiles = !ui.home && !grid_on() &&              /* ((Skiff 2.0) NOTES, FEEL, PATTERN: their hints; (issue #3) not */
                (pg->graph == GR_ROLL || pg->graph == GR_FEEL || pg->graph == GR_STEPS);   /* under HOME's */
    int hints = act_cols() || ((grid_on() || tiles) && !ui_hints_off);   /* (the line says them, not the
                                                       * sound; (Skiff U4) MENU > HINTS OFF: the sound) */
    uint32_t ret = mom_down() && mom_held(0) ? 1u + ret_mode() : 0u;   /* ((2.0, D 2A) MOMENTARY: how its values */
                                                       /* come back, OCT+ KEEP, for the whole line */
    sound_name(t, pn);
    if (ui.home)
        ti[0] = 0;                                     /* ((Skiff U4, L5) the header names the page: here only where it */
    else                                               /* is in its family, "2/2" (was "ENV DEST 2/2", "HOME") */
        page_pos(ti);                                  /* (a sheet too, #7) */
    str_cpy(s, ename, sizeof s);
    s[str_len(s) + 1u] = 0;
    s[str_len(s)] = (char)('1' + song.sel);
    str_cpy(s + str_len(s), pn, 16);
    str_cpy(s + str_len(s), ti, sizeof ti);
    {   /* step markers: the playhead only when it is in the shown bank, the cursor only in SEQ */
        uint32_t ph = song.playing && t->seq_idx / 16u == ui.bank ? t->seq_idx : 0xFFu;
        sig = str_hash(0x9E3779B9u, s) + ph * 97u + (song.seq_mode ? ui.cursor : 0xFFu) * 3001u + steps_hash(t) +
              (ui.home ? 0u : page_icon(pg)) * 7121u +
              ui.bank * 7u + (uint32_t)t->p[P_SLEN] * 13u + list_mode() * 9173u + (ui.edge_t != 0) * 5501u +
              ui_hints_off * 3301u;
    }
    if (act_cols()) {                                  /* the hint, and whether OCT+ would act */
        char ha[24], hb[16];
        foot_hint(ha, hb);
        sig += str_hash(str_hash(act_ready() ? 7u : 3u, ha), hb) + (uint32_t)ui.act2 * 7717u + (uint32_t)ui.ev_del * 1931u;
        if (pg->graph == GR_SONG)                      /* ((Skiff phase 5) SONG's: the whole of it, EDIT's; (2.0, #30) */
            sig += str_hash(5u, song_act_name()) + (uint32_t)bank_used(song.sel, sg.entry) * 6007u +   /* the entry's */
                   (uint32_t)lists.snd[song.sel % NTRK][sg.entry % NENT][0] * 131u +                     /* sound */
                   (uint32_t)lists.snd[song.sel % NTRK][sg.entry % NENT][1] * 7u + up_gen * 0x3BD1u;
    }
    if (grid_on())
        sig += 0x51EDu + (uint32_t)black_held(GK_ACC) * 977u;
    if (tiles)                                         /* (Skiff U1) the REC hint comes and goes with the arming */
        sig += ((song.rec >> song.sel) & 1u) * 4421u;
    if (ui.ml.on) {                                    /* ((1.3) MIDI LEARN's line) */
        char ln[24];
        ml_line(ln);
        sig += str_hash(0x4C45u, ln);
    }
    sig += ret * 0x2E7B5u;
    if (!ui.force && sig == ui.foot_sig)
        return;
    ui.foot_sig = sig;
    cv_begin(240, foot_h(), T_BG);
    if (ux.neon)                                       /* (Skiff N3) NEON: a neon rule over it */
        ne_rule(0, 1);
    if (ux.quark)                                      /* (Skiff Q2) QUARK: a dotted rule */
        qk_rule(0);
    if (ui.ml.on && !act_cols()) {                    /* ((1.3) MIDI LEARN: what is picked and its CC, OCT+ DONE at the
                                                       * right, for the whole line (midi_learn.c ml_line) */
        char ln[24];
        int32_t w = kh_w(KC_OCTUP, "DONE");
        ml_line(ln);
        cv_free_text(8, ly, &AF_S, ln, T_ACCENT, T_BG, 232 - w - 10 - 8);
        cv_key_hint(232 - w, ly - KC_TY, KC_OCTUP, "DONE", 1, T_BG);
        cv_blit(0, foot_y());
        return;
    }
    if (ret) {                                         /* ((2.0, D 2A) MOMENTARY: LET GO: BACK OVER 1 BAR, OCT+: KEEP) */
        ret_hints(ret, ly);
        cv_blit(0, foot_y());
        return;
    }
    if (act_cols() && pg->graph == GR_SONG) {         /* (Skiff phase 5) SONG: what OCT+ does, then EDIT CLEAR (not with
                                                       * a pick), side by side (the mockup's), the title right */
        khint_t kh[1] = {{KC_OCTUP, song_act_name()}};   /* ((Skiff U2) CLEAR: KNOB 2's, no EDIT) */
        uint32_t n = 1u;
        int32_t r = foot_hint_r(ti), w = kh_w(kh[0].key, kh[0].act);
        char sn[24];
        cv_key_row(8, 8 + w < r ? 8 + w : r, ly - KC_TY, kh, n,
                   (act_ready() ? 1u : 0u) | (bank_used(song.sel, sg.entry) ? 2u : 0u), T_BG);
        str_cpy(sn, "SOUND ", sizeof sn);              /* ((2.0, #30, the user's pick 2A) no pick: the entry's sound */
        esnd_name(lists.snd[song.sel % NTRK][sg.entry % NENT], sn + 6);   /* named after it) */
        if (!song_pick() && sn[6] && 8 + w + 10 < r)
            cv_free_text(8 + w + 10, ly, &AF_S, sn, T_MID, T_BG, r - (8 + w + 10));
    } else if (act_cols()) {                          /* the OCT+ / OCT- hint ((Skiff U2) EDIT's NAME / DELETE gone) */
        char ha[24], hb[16];
        khint_t kh[2];
        foot_hint(ha, hb);                            /* "OCT+ LOAD", "OCT- HOME": their words */
        kh[0] = (khint_t){KC_OCTUP, ha + 5};
        kh[1] = (khint_t){KC_OCTDN, hb + 5};
        {                                             /* (Skiff) the hints' room on the one line: the title's name */
            uint32_t j;                               /* gives way first (the header says it), its n/m stays */
            int32_t need = 6 + kh_w(kh[0].key, kh[0].act) + kh_w(kh[1].key, kh[1].act);
            char *sp = 0;
            for (j = 0; ti[j]; j++)
                if (ti[j] == ' ')
                    sp = &ti[j];
            if (8 + need > foot_hint_r(ti) && sp)
                str_cpy(ti, sp + 1, sizeof ti);
        }
        {
            int32_t x1 = foot_hint_r(ti), w = kh_w(kh[0].key, kh[0].act) + 8 + kh_w(kh[1].key, kh[1].act);
            if (pg->graph == GR_BANK && 8 + w < x1)    /* ((Skiff phase 5) the pool view: side by side, the mockup's) */
                x1 = 8 + w;
            cv_key_row(8, x1, ly - KC_TY, kh, 2, act_ready() ? 3u : 2u, T_BG);
        }
    } else if (grid_on() && !ui_hints_off) {          /* row 1: the page, and what the keys do */
        char b[16];
        uint32_t all, off = step_off(&all, 16);         /* ((2.0, #44) a chain's pages counted on: PAGE 5/8) */
        str_cpy(b, "PAGE ", sizeof b);
        fmt_kn(b + 5, (int32_t)(off + ui.bank) + 1, (int32_t)all);
        x = cv_text(8, ly, &AF_S, b, T_THEME) + 10;   /* (Skiff) the page, then the keys, on the line */
        if (black_held(GK_ACC))
            cv_text(x, ly, &AF_S, "ACCENT", T_ACCENT);
        else
            cv_key_hint(x, ly - KC_TY, KC_KEYS, "STEPS", 1, T_BG);
    } else if (tiles && !ui_hints_off) {               /* (Skiff 2.0) NOTES, FEEL: PRESETS the cursor (SHIFT + PRESETS, the
                                                        * selection: SHIFT's map); NOTES' keys (REC off: they pick, on:
                                                        * they write); PATTERN's PRESETS */
        if (pg->graph == GR_STEPS) {
            cv_key_hint(8, ly - KC_TY, KC_PRESETS, "DIR", 1, T_BG);
        } else {
#if BOARD_SMK37
            x = cv_key_hint(8, ly - KC_TY, KC_K4, "STEP", 1, T_BG) + 10;   /* (K4 is PRESETS) */
#else
            x = cv_key_hint(8, ly - KC_TY, KC_PRESETS, "STEP", 1, T_BG) + 10;
#endif
            if (pg->graph == GR_ROLL)
                cv_key_hint(x, ly - KC_TY, KC_KEYS, (song.rec >> song.sel) & 1u ? "WRITE" : "PICK", 1, T_BG);
        }
    }
    {   /* the track's cushion, engine name, sound, page title at the right with its icon before it (MIXER, SONG,
         * CHANCE, AUTOMATION); icons: their ink on the names' capitals */
        uint32_t pi = ui.home ? ICON_NONE : page_icon(pg);
        int32_t r = 232, tx, ex, need = text_w(&AF_S, pn), ew = text_w(&AF_S, ename);
        ex = 8 + 16 + 5 + (ew < 80 ? ew : 80);        /* (where the engine's name ends) */
        tx = r - text_w(&AF_S, ti) - (pi != ICON_NONE ? 16 : 0);
        (void)need;
        if (home_lanes() && !ui_hints_off)             /* Skiff BLOCKS on HOME: the lanes name the sounds; the hint */
#if BOARD_SMK37
            cv_free_hint(8, ly, "HOLD [KNOB BANK] SHIFT", T_MID, T_BG, 160);   /* (SMK37_UX.md extra buttons A) */
#else
            cv_free_hint(8, ly, "HOLD [HOME] SHIFT", T_MID, T_BG, 160);
#endif
        if ((home_lanes() && !ui_hints_off) || hints) {   /* (an action page's or a grid's hints: the title) */
            if (pi != ICON_NONE) {
                GFX_HOOK_ALIGN(0, ly + AF_S_CAP_Y, 0, ly + AF_S_CAP_Y + AF_S_CAP_H, AL_V, "footer icons on the names' line");
                cv_icon_in(tx, ly + AF_S_CAP_Y, 0, AF_S_CAP_H, 12, pi, T_MID, T_BG);
            }
            cv_text_r(r, ly, &AF_S, ti, ui.edge_t ? T_ACCENT : T_MID, T_BG);   /* ((U4, F7) an end) */
            cv_blit(0, foot_y());
            return;
        }
        x = 8;                                         /* (Skiff) the selected track's cushion (not the header's) */
        GFX_HOOK_ALIGN(0, ly + AF_S_CAP_Y, 0, ly + AF_S_CAP_Y + AF_S_CAP_H, AL_V, "footer icons on the names' line");
        x += cv_icon_in(x, ly + AF_S_CAP_Y, 0, AF_S_CAP_H, 16, trk_icon(song.sel, 1), T_ACCENT, T_BG) + 5;
        x = cv_text_fit(x, ly, &AF_S, ename, T_THEME, T_BG, 80);
        if (list_mode())                               /* ((Skiff U2) PRESETS lists the favourites; phase 9: a type) */
            x = cv_text(x + 6, ly, &AF_S, LIST_NAME[list_mode()], T_ACCENT);
        cv_free_text(x + 10, ly, &AF_S, pn, T_TEXT, T_BG, tx - 12 - (x + 10));
        if (pi != ICON_NONE) {
            GFX_HOOK_ALIGN(0, ly + AF_S_CAP_Y, 0, ly + AF_S_CAP_Y + AF_S_CAP_H, AL_V,
                           "footer icons on the names' line");
            cv_icon_in(tx, ly + AF_S_CAP_Y, 0, AF_S_CAP_H, 12, pi, T_MID, T_BG);
        }
        cv_text_r(r, ly, &AF_S, ti, ui.edge_t ? T_ACCENT : T_MID, T_BG);
    }
    cv_blit(0, foot_y());
}

static void formant_note_on(track_t *t, voice_t *v)
{
    (void)t;
    v->s[7] = (int32_t)((noise32(&FORMANT_NZ(t)) >> 25) << 25);   /* TALK starts over; a random vowel (RAND) */
    if (!v->env && !v->env_out) {                       /* a fresh voice (not a retrigger): from rest */
        uint32_t i;
        v->ph[0] = 0;                                   /* the opening starts at zero: no click */
        v->ph[1] = v->ph[2] = 0;
        for (i = 0; i < 7u; i++)
            v->s[i] = 0;
    }
}

static void formant_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const int16_t *p = t->p;
    fres_t r1, r2, r3, r4;
    int32_t fa[3], ba[3], fb[3], bb[3], k, j, buzz, oq, tilt, gv, gn, og, ogk;
    uint32_t inc = m->inc, i, te, tp, rp, rn, ratio, bws, f0;
    uint32_t ph = v->ph[0];
    int32_t y1 = v->s[0], y2 = v->s[1], y3 = v->s[2], y4 = v->s[3], y5 = v->s[4], y6 = v->s[5];
    int32_t y7 = (int32_t)v->ph[1], y8 = (int32_t)v->ph[2], lp = v->s[6], nst = FORMANT_NZ(t);

    /* vowel: VOWEL -> VOWL2 over TALK after note-on; ENV / LFO -> FLT move both */
    k = 0;
    if (p[P_E2]) {
        uint32_t g = ((uint32_t)v->s[7] & FMT_TALK_MASK) + ENV_LIN[p[P_E2] & 127];
        g = g > (1u << 24) ? 1u << 24 : g;
        v->s[7] = (int32_t)(((uint32_t)v->s[7] & ~(uint32_t)FMT_TALK_MASK) | g);
        k = (int32_t)(g >> 9);                          /* Q15 */
        k = (k * (65536 - k)) >> 15;                    /* ease out: the mouth opens fast, then settles */
    }
    {   /* RAND: both vowels move towards this note's random vowel (0 = off, 127 = fully random) */
        int32_t rv = (int32_t)(((uint32_t)v->s[7] >> 25) << 8), v0 = p[P_E0] << 8, v1 = p[P_E1] << 8;
        v0 += ((rv - v0) * p[P_E7] * 258) >> 15;
        v1 += ((rv - v1) * p[P_E7] * 258) >> 15;
        vowel_at(v0 + m->cutoff, fa, ba);
        vowel_at(v1 + m->cutoff, fb, bb);
    }
    /* SHIFT (semitones) and FOLOW (key tracking around C4, fixed), one ratio for all four */
    ratio = fmt_ratio(p[P_E3] * 16 + ((FMT_FOLOW * (v->pitch_cur - 60 * 16) * 516) >> 16));   /* FOLOW / 127 */
    bws = fmt_ratio((64 - p[P_E6]) * 4);                /* Q: bandwidth x2.5 .. x0.4 */
    f0 = (uint32_t)(((uint64_t)inc * 705600u) >> 32);   /* F0 in Hz * 16 */
    for (j = 0; j < 3; j++) {
        int32_t f = fa[j] + (((fb[j] - fa[j]) * k) >> 15), b = ba[j] + (((bb[j] - ba[j]) * k) >> 15);
        f = (int32_t)(((int64_t)f * ratio) >> 16);
        b = (int32_t)(((((int64_t)b * ratio) >> 16) * bws) >> 16);
        if (j == 0 && (uint32_t)f < f0 + (f0 >> 4) && f > 0) {   /* sung high: F1 follows F0 (sopranos do), */
            b = (int32_t)(((int64_t)b * (int32_t)(f0 + (f0 >> 4))) / f);   /* same Q: no boom on the fundamental */
            f = (int32_t)(f0 + (f0 >> 4));
        }
        fa[j] = clamp(f, 60 * 16, 7000 * 16);
        ba[j] = clamp(b, 20 * 16, 1500 * 16);
    }
    fres_coef(&r1, (uint32_t)fa[0], (uint32_t)ba[0]);
    fres_coef(&r2, (uint32_t)fa[1], (uint32_t)ba[1]);
    fres_coef(&r3, (uint32_t)fa[2], (uint32_t)ba[2]);
    fres_coef(&r4, (uint32_t)clamp((int32_t)((3300u * 16u * (uint64_t)ratio) >> 16), 60 * 16, 7000 * 16),
              (uint32_t)clamp((int32_t)((((250u * 16u * (uint64_t)ratio) >> 16) * bws) >> 16), 20 * 16, 1500 * 16));

    /* source: BUZZ (+ SHP modulation, + velocity) -> open quotient and tilt */
    buzz = clamp((p[P_E4] << 8) + m->shape - (64 << 8) + (v->vel - 96) * 40, 0, 127 << 8);
    oq = 58982 - ((buzz * 284) >> 8);                   /* Q16: 0.90 .. 0.35 */
    tilt = 2500 + ((buzz * 109) >> 8);                  /* one-pole coefficient Q14: dark .. open */
    te = (uint32_t)oq << 16;                            /* closure (end of the open phase) */
    tp = (te >> 8) * 166u;                              /* opening: 65 % of it, closing 35 % */
    rp = (1u << 30) / ((tp >> 16) | 1u);
    rn = (1u << 30) / (((te - tp) >> 16) | 1u);
    gv = 32767 - p[P_E5] * p[P_E5] * 2;                 /* BREATH: voicing fades at the top */
    gn = p[P_E5] * 258;                                 /* noise: Q15, up to 1.0 */
    og = 13000 - ((p[P_E6] - 64) * 50);                 /* output: narrower bands ring louder */
    og = (int32_t)(((int64_t)og * fmt_ratio((60 * 16 - v->pitch_cur) / 4)) >> 16);   /* 1.5 dB / oct: low notes are sparse pulses */
    ogk = (og >> 2) * (4 + (buzz >> 10));               /* presence k = 1 .. 4.9 */

    for (i = 0; i < n; i++) {
        int32_t e, x, a, s;
        if (ph < tp)                                    /* opening: + sin(pi u) * Tn / Tp */
            e = (sine_i(((ph >> 16) * rp) << 1) * 17644) >> 15;
        else if (ph < te)                               /* closing: - sin(pi / 2 u) */
            e = -sine_i(((ph - tp) >> 16) * rn);
        else
            e = 0;
        e += blep(ph - te, inc) >> 1;                   /* the closure step, band-limited */
        lp += ((e - lp) * tilt) >> 14;
        x = (lp * gv) >> 15;
        if (gn) {
            int32_t nz = (((int32_t)(noise32(&nst) >> 16) - 32768) * gn) >> 15;
            x += ph < te ? nz : nz >> 1;                /* aspiration follows the glottal opening */
        }
        /* F1 -> F2 -> F3 -> F4, Q30, rounded; the signal x 64 inside: the rounding
         * dead band of F1 (+-0.5 / A, ~340 at 270 Hz) stays below 6 LSB */
        a = (int32_t)(((int64_t)r1.a * (x << 6) + (int64_t)r1.b * y1 + (int64_t)r1.c * y2 + (1 << 29)) >> 30);
        y2 = y1;
        y1 = a;
        a = (int32_t)(((int64_t)r2.a * a + (int64_t)r2.b * y3 + (int64_t)r2.c * y4 + (1 << 29)) >> 30);
        y4 = y3;
        y3 = a;
        a = (int32_t)(((int64_t)r3.a * a + (int64_t)r3.b * y5 + (int64_t)r3.c * y6 + (1 << 29)) >> 30);
        y6 = y5;
        y5 = a;
        a = (int32_t)(((int64_t)r4.a * a + (int64_t)r4.b * y7 + (int64_t)r4.c * y8 + (1 << 29)) >> 30);
        y8 = y7;
        y7 = clamp(a, -(1 << 28), 1 << 28);             /* int32 state stays far from overflow */
        s = soft_knee(clamp((int32_t)(((int64_t)y7 * og + (int64_t)(y7 - y8) * ogk) >> 21), -200000, 200000), 24000);
        ph += inc;
        out[i] += voice_amp(s, m, i) << 1;
    }
    v->ph[0] = ph;
    v->ph[1] = (uint32_t)y7;
    v->ph[2] = (uint32_t)y8;
    FORMANT_NZ(t) = nst;
    v->s[0] = y1;
    v->s[1] = y2;
    v->s[2] = y3;
    v->s[3] = y4;
    v->s[4] = y5;
    v->s[5] = y6;
    v->s[6] = lp;
}

static const param_desc_t *phys_desc(const track_t *t, uint32_t k)
{
    return k < 8u ? PHYS_DESC[(uint32_t)t->p[P_E0] % PM_COUNT][k] : 0;
}

/* p16 -> one-pole coefficient, Q15: w / (1 + w), w = 2 pi f / fs */
static int32_t dv_pole(int32_t p16)
{
    int32_t w = (int32_t)(((DV_P16(p16) >> 17) * 205887u) >> 15);
    return (w << 15) / (32768 + w);
}

static void drumx_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const int16_t *p = t->p;
    drumx_lane_t *L = drumx_lane_of(t, v);
    uint32_t lane = (uint32_t)v->s[0] & (DV_NLANE - 1u), i;
    int32_t y[CTL], drv = p[P_E7], g = 0, mk = 0;
    vmod_t ml;
    if (!L)
        return;
    m = vmod_level(m, &ml, clamp(p[P_LN0 + lane], 0, 127));   /* the lane's LEVEL, as DRUM's (dsp.c) */
    if (n > CTL)
        n = CTL;
    dx_run(&dx_kit[lane], &L->x, p[P_E0], L->st * 16 + (p[P_E1] - 64) * 3, p[P_E3] - 64, p[P_E2] - 64, p[P_E4] - 64,
           p[P_E6], p[P_E5], y, n);
    if ((drum_mute[(uint32_t)(t - trk) % NTRK] >> lane) & 1u)
        return;                                          /* ((1.3) a muted lane rings on unheard, as DRUM's) */
    if (drv > 0) {                                       /* DRV: x1..x4 into the soft clip, the level kept (Q12) */
        g = 4096 + drv * 3 * 4096 / 127;
        mk = (int32_t)((19661u << 15) / (uint32_t)softclip((19661 * g) >> 12));
    }
    for (i = 0; i < n; i++) {                            /* x1.25 and the knee below, in 32 bits (as DRUM's) */
        int32_t s = y[i];
        if (g)
            s = (softclip((s * g) >> 12) * mk) >> 15;
        out[i] += voice_amp(soft_knee(s + (s >> 2), 24000), m, i) << 1;
    }
}

/* the voice's amplitude: the hit, not the ADSR (held at full so a release never ends it). A voice that plays no
 * lane any more, or whose hit has rung out, ends here */
static int32_t drumx_amp(track_t *t, voice_t *v, int32_t adsr)
{
    const drumx_lane_t *L = drumx_lane_of(t, v);
    (void)adsr;
    if (!v->active)                                      /* (taken for another part: env_tick ended it) */
        return 0;
    if (!L || (!L->x.live && !L->x.trig)) {
        v->active = v->gate = 0;
        v->stage = 0;
        v->env = 0;
        return 0;
    }
    v->env = 1 << 24;
    return 32767;
}

/* a line in c over its shadow ((FM6 LAB T) NEON: over its glow, a tube's) */
static void fm_seg2(int32_t xa, int32_t ya, int32_t xb, int32_t yb, int32_t w, uint16_t c)
{
    if (ux.neon)
        fm_seg(xa, ya, xb, yb, w + 2, ux_mix(c, T_SURF, 62), 0, 0);
    else
        fm_seg(xa, ya + 1, xb, yb + 1, w, T_BG, 0, 0);
    fm_seg(xa, ya, xb, yb, w, c, 0, 0);
}
